import {effectTagRoles,editEffectTagRequirements} from './effect-tag-requirements.js';
// Uses the structured editor's existing copy/validate/Undo/save transaction.
export function effectTagEditor(document,doc,index,edit){
 const owner=index===null?doc.data:doc.data.modifiers[index],key=index===null?'applicationRequirements':'tagRequirements',value=owner[key],root=document.createElement('fieldset'),legend=document.createElement('legend'),toggle=document.createElement('button');root.dataset.effectTagRequirements=index===null?'application':String(index);legend.textContent=index===null?'효과 적용 태그 조건':'변경 항목 태그 조건';root.append(legend);toggle.type='button';toggle.textContent=value?'조건 제거':'조건 추가';toggle.dataset.effectTagToggle='';toggle.onclick=()=>edit(data=>editEffectTagRequirements(data,index,value?undefined:{source:{all:[],any:[],none:[]}}));root.append(toggle);if(!value)return root;
 const labels={source:'출처',target:'대상',instigator:'발동자',causer:'원인'};
 for(const role of effectTagRoles){const group=document.createElement('div'),title=document.createElement('strong');title.textContent=labels[role];group.append(title);for(const [mode,label]of [['all','모두 필요'],['any','하나 이상'],['none','차단']]){const line=document.createElement('label'),input=document.createElement('input');input.value=(value[role]?.[mode]||[]).join(', ');input.dataset.effectTagRole=role;input.dataset.effectTagMode=mode;input.setAttribute('aria-label',labels[role]+' '+label);line.append(label,input);group.append(line);input.onchange=()=>edit(data=>{const requirements=index===null?structuredClone(data.applicationRequirements):structuredClone(data.modifiers[index].tagRequirements);requirements[role]??={};requirements[role][mode]=input.value.split(',').map(s=>s.trim()).filter(Boolean);editEffectTagRequirements(data,index,requirements);});}
 const line=document.createElement('label'),exact=document.createElement('input');exact.type='checkbox';exact.checked=!!value[role]?.exact;exact.dataset.effectTagExact=role;exact.setAttribute('aria-label',labels[role]+' 정확한 태그');line.append('정확한 태그',exact);group.append(line);exact.onchange=()=>edit(data=>{const requirements=structuredClone(index===null?data.applicationRequirements:data.modifiers[index].tagRequirements);requirements[role]??={};requirements[role].exact=exact.checked;editEffectTagRequirements(data,index,requirements);});root.append(group);}
 return root;
}
